import * as THREE from './vendor/three.module.min.js';
const $=s=>document.querySelector(s),C=CalendarCore,L=LunarCalc,Z=ZodiacCalc,D=ZodiacData,canvas=$('#skyCanvas'),range=$('#skyTime'),page=$('#celestial-sky');
const fmt=n=>new Intl.NumberFormat('ar',{maximumFractionDigits:1}).format(n),state={date:L.dateISO(new Date(),C.location.zone),yaw:.3,pitch:.4,zoom:1,layer:0};let renderer=null,ctx=null,timer=null,drag=null;
const fields=document.createElement('div');fields.className='sky-live-fields';fields.innerHTML='<label>التاريخ المحلي <input id="skyDate" type="date" min="1900-01-01" max="2100-12-31"></label><button id="skyNow">الآن</button><span id="skyLocation"></span>';page.querySelector('.sky-lab').before(fields);$('#skyDate').value=state.date;
const caption=document.createElement('p');caption.className='live-caption';caption.textContent='نجوم J2000 محوّلة إلى أفق الموقع، مع الشمس والقمر المحسوبين. اسحب للدوران ومرّر للتكبير. أحجام الأجرام مكبّرة للتوضيح؛ لا تشمل الخريطة الطقس أو التضاريس.';page.querySelector('.sky-lab').after(caption);
page.querySelector('.sky-labels').hidden=true;
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(42,1,.1,100),group=new THREE.Group();camera.position.set(0,.3,3.3);camera.lookAt(0,0,0);scene.add(group);
try{renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio||1,2));}catch{ctx=canvas.getContext('2d');caption.textContent+=' العرض الحالي إسقاط ثنائي الأبعاد لعدم توفر WebGL.';}
const toV=p=>new THREE.Vector3(-p[1],p[2],-p[0]);
function dispose(){for(const child of [...group.children]){group.remove(child);child.geometry?.dispose();if(Array.isArray(child.material))child.material.forEach(m=>m.dispose());else child.material?.dispose();}}
function line(points,color,opacity=.45){const geo=new THREE.BufferGeometry().setFromPoints(points.map(toV)),obj=new THREE.Line(geo,new THREE.LineBasicMaterial({color,transparent:true,opacity}));group.add(obj);}
function now(){const n=new Date();state.date=L.dateISO(n,C.location.zone);$('#skyDate').value=state.date;const b=L.dayBounds(state.date,C.location.zone);range.max=Math.round((b.end-b.start)/60000)-1;range.value=Math.floor((n-b.start)/60000);draw();}
function draw(){
 if(!page.classList.contains('active'))return;
 try{const loc=C.location,b=L.dayBounds(state.date,loc.zone);range.max=Math.round((b.end-b.start)/60000)-1;const date=new Date(+b.start+Number(range.value)*60000),f=Z.frame(date,loc),rect=canvas.getBoundingClientRect();if(rect.width<1||rect.height<1)return;$('#skyClock').textContent=C.clock(date);page.querySelector('.sky-controls small').textContent=C.format(date);$('#skyLocation').textContent=loc.name+' • '+loc.zone;
 const stars=D.stars.filter(s=>s.mag<=5.5).map(s=>({s,h:Z.star(s,f)})),sun=Z.body('Sun',f),moon=Z.body('Moon',f);for(const [name,h] of [['sun',sun],['moon',moon]]){textCard(name,h);}
 if(renderer){dispose();const positions=[],colors=[];for(const {h} of stars){const v=toV(h.p);positions.push(v.x,v.y,v.z);const k=h.altitude>=0?.9:.22;colors.push(k,k*.95,k);}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));group.add(new THREE.Points(geo,new THREE.PointsMaterial({size:.009,vertexColors:true,sizeAttenuation:true})));
 const horizon=[];for(let i=0;i<=180;i++){const a=i*Math.PI/90;horizon.push([Math.cos(a),Math.sin(a),0]);}line(horizon,0x55d8f2,.85);
 for(const alt of [30,60]){const pts=[];for(let i=0;i<=180;i++){const a=i*Math.PI/90,r=Math.cos(alt*Math.PI/180);pts.push([r*Math.cos(a),r*Math.sin(a),Math.sin(alt*Math.PI/180)]);}if(state.layer===0)line(pts,0x55d8f2,.2);}
 const path=[];for(let n=0;n<=360;n+=2){if(state.layer===1)path.push(Z.point(n,0,f));if(state.layer===2)path.push(Z.ecliptic(n,0,f));}if(path.length)line(path,state.layer===1?0x8bcdff:0xf6c85f,.9);
 for(const [h,color,size] of [[sun,0xffd363,.043],[moon,0xdbe6ec,.031]]){const mesh=new THREE.Mesh(new THREE.SphereGeometry(size,16,12),new THREE.MeshBasicMaterial({color,transparent:true,opacity:h.altitude<0?.35:1}));mesh.position.copy(toV(h.p));group.add(mesh);}
 const axes=new THREE.AxesHelper(.15);group.add(axes);group.rotation.set(state.pitch,state.yaw,0);camera.aspect=rect.width/rect.height;camera.position.z=3.3/state.zoom;camera.updateProjectionMatrix();renderer.setSize(rect.width,rect.height,false);renderer.render(scene,camera);
 }else if(ctx){const d=Math.min(devicePixelRatio||1,2);canvas.width=rect.width*d;canvas.height=rect.height*d;ctx.setTransform(d,0,0,d,0,0);const w=rect.width,h=rect.height,r=Math.min(w,h)*.4;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#55d8f2';ctx.beginPath();ctx.arc(w/2,h/2,r,0,Math.PI*2);ctx.stroke();for(const {h:p,s} of stars){if(p.altitude<0)continue;const a=(p.azimuth*Math.PI/180+state.yaw),rr=(90-p.altitude)/90*r;ctx.fillStyle='#d5efff';ctx.beginPath();ctx.arc(w/2+Math.sin(a)*rr,h/2-Math.cos(a)*rr,Math.max(.7,2-s.mag*.2),0,Math.PI*2);ctx.fill();}for(const [p,color]of[[sun,'#ffd363'],[moon,'#e0e9f1']])if(p.altitude>=0){const a=p.azimuth*Math.PI/180+state.yaw,rr=(90-p.altitude)/90*r;ctx.fillStyle=color;ctx.beginPath();ctx.arc(w/2+Math.sin(a)*rr,h/2-Math.cos(a)*rr,6,0,Math.PI*2);ctx.fill();}}
 }catch(error){caption.textContent='تعذّر حساب المشهد: '+error.message;}
}
function textCard(name,h){page.querySelector('.'+name+'-object small').textContent='ارتفاع '+fmt(h.altitude)+'° • سمت '+fmt(h.azimuth)+'°';}
range.oninput=draw;$('#skyDate').onchange=e=>{if(e.target.value>='1900-01-01'&&e.target.value<='2100-12-31'){state.date=e.target.value;draw();}else showToast('اختر تاريخًا بين ١٩٠٠ و٢١٠٠');};$('#skyNow').onclick=now;page.querySelector('[aria-label="إعادة الضبط"]').onclick=()=>{state.yaw=.3;state.pitch=.4;state.zoom=1;now();};
const layers=[...page.querySelectorAll('.segmented button')];layers.forEach((b,i)=>b.onclick=()=>{state.layer=i;layers.forEach((x,j)=>{x.classList.toggle('active',i===j);x.setAttribute('aria-pressed',String(i===j));});draw();});
$('#skyPlay').onclick=e=>{if(timer){clearInterval(timer);timer=null;e.currentTarget.textContent='▶';}else{e.currentTarget.textContent='Ⅱ';timer=setInterval(()=>{if(!page.classList.contains('active')||document.hidden)return;range.value=(+range.value+4)%(+range.max+1);draw();},150);}};
canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!drag)return;state.yaw+=(e.clientX-drag.x)*.008;state.pitch=Math.max(-1.4,Math.min(1.4,state.pitch+(e.clientY-drag.y)*.008));drag={x:e.clientX,y:e.clientY};draw();};for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,()=>drag=null);canvas.addEventListener('wheel',e=>{e.preventDefault();state.zoom=Math.max(.7,Math.min(1.9,state.zoom*(e.deltaY<0?1.08:.92)));draw();},{passive:false});
addEventListener('resize',draw);addEventListener('calendar-location',now);window.skyLive={draw};now();
